#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# NAISEMA launch setup: the accounts and secrets only a person can create.
# Usage: scripts/launch-wizard.sh [staging|production]
# Re-runnable: secrets already set on the Worker are skipped unless you say replace.
# Secrets go straight to Cloudflare (wrangler secret put) or GitHub; none is
# written to a file. See docs/handover/runbook.md for the reasons behind each step.

TOTAL_STAGES=13

REPO="naisema-fj/naisema"
CF_CONFIG="wrangler.jsonc"
WORKER_SET=()      # Worker secrets set this run
GH_ENV_SET=()      # GitHub environment secrets set this run
SECRET_NAMES=""    # names of secrets currently on the Worker

ENV_NAME="${1:-}"
if [[ "$ENV_NAME" != "staging" && "$ENV_NAME" != "production" ]]; then
  printf '\nWhich environment are you setting up? [staging/production] '
  read -r ENV_NAME || true
  if [[ "$ENV_NAME" != "staging" && "$ENV_NAME" != "production" ]]; then
    printf 'Please type staging or production.\n' >&2
    exit 1
  fi
fi

if [[ ! -f "$CF_CONFIG" || ! -f package.json ]]; then
  printf 'Run this from the root of the naisema repository.\n' >&2
  exit 1
fi

CF_ACCOUNT_ID=$(grep -oE '"CLOUDFLARE_ACCOUNT_ID": *"[0-9a-f]{32}"' "$CF_CONFIG" | head -n1 | grep -oE '[0-9a-f]{32}' || true)

# ── Helpers for this wizard (the library above is untouched) ───────────────

wr() { pnpm --silent wrangler "$@"; }

# refresh_secrets reads which secrets the Worker has now. Sets SECRET_NAMES;
# returns non-zero if Cloudflare could not be asked.
refresh_secrets() {
  local out
  out=$(wr secret list --env "$ENV_NAME" --config "$CF_CONFIG" --format json 2>/dev/null) || return 1
  SECRET_NAMES=$(printf '%s' "$out" | node -e '
    let s = ""; process.stdin.on("data", d => s += d).on("end", () => {
      try { for (const x of JSON.parse(s)) console.log(x.name); } catch { process.exit(1); }
    });') || return 1
}

has_secret() { grep -qx "$1" <<<"$SECRET_NAMES"; }

# want_secret NAME: true if NAME should be (re)set now. A secret that exists is
# kept unless the human says replace.
want_secret() {
  if has_secret "$1"; then
    note "$1 is already set on the $ENV_NAME Worker."
    confirm "Replace it? (cannot be undone)"
    return
  fi
  return 0
}

# put_secret NAME VALUE sends the value to the Worker on stdin (never as an argument).
put_secret() {
  local name="$1" value="$2" log
  log=$(mktemp)
  if printf '%s' "$value" | wr secret put "$name" --env "$ENV_NAME" --config "$CF_CONFIG" >"$log" 2>&1; then
    WORKER_SET+=("$name")
    printf '  %s✓ set%s Worker secret %s (%s)\n' "$GREEN" "$RESET" "$name" "$ENV_NAME"
    SECRET_NAMES="${SECRET_NAMES}"$'\n'"$name"
  else
    SKIPPED+=("Worker secret $name: wrangler said: $(tail -n 2 "$log" | tr '\n' ' ')")
    warn "could not set $name; see the list at the end"
  fi
  rm -f "$log"
}

# set_env_secret NAME VALUE sets a GitHub environment secret (CI reads these).
set_env_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1 \
     && printf '%s' "$value" | gh secret set "$name" --env "$ENV_NAME" --repo "$REPO" >/dev/null 2>&1; then
    GH_ENV_SET+=("$name")
    printf '  %s✓ set%s GitHub %s environment secret %s\n' "$GREEN" "$RESET" "$ENV_NAME" "$name"
  else
    SKIPPED+=("GitHub $ENV_NAME environment secret $name (gh secret set $name --env $ENV_NAME --repo $REPO)")
    warn "could not set GitHub secret $name; see the list at the end"
  fi
}

# json_field 'expression on x' reads JSON on stdin and prints the expression's value.
json_field() {
  node -e '
    let s = ""; process.stdin.on("data", d => s += d).on("end", () => {
      try { const x = JSON.parse(s); const v = (new Function("x", "return " + process.argv[1]))(x); if (v === undefined || v === null) process.exit(1); console.log(v); }
      catch { process.exit(1); }
    });' "$1"
}

# cf_api METHOD PATH TOKEN [DATA] calls the Cloudflare API without the token
# appearing in the process list.
cf_api() {
  local method="$1" path="$2" token="$3" data="${4:-}"
  local args=(-sS -X "$method" --config - "https://api.cloudflare.com/client/v4${path}")
  [[ -n "$data" ]] && args+=(-H "Content-Type: application/json" --data "$data")
  printf 'header = "Authorization: Bearer %s"\n' "$token" | curl "${args[@]}"
}

banner "NAISEMA launch setup: ${ENV_NAME}"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Check your tools and sign-ins"
say "Everything below runs against the ${BOLD}${ENV_NAME}${RESET} environment."
say "You need pnpm, openssl, curl and node here, and to be signed in to Cloudflare and GitHub."
missing=()
for tool in pnpm openssl curl node; do command -v "$tool" >/dev/null 2>&1 || missing+=("$tool"); done
if (( ${#missing[@]} )); then
  warn "missing: ${missing[*]}. Install them, then re-run."
  exit 1
fi
if [[ ! -d node_modules ]]; then
  say "Installing dependencies (pnpm install)..."
  pnpm install --frozen-lockfile
fi
if ! wr whoami >/dev/null 2>&1; then
  say "Not signed in to Cloudflare. A browser window will open."
  pnpm wrangler login
fi
note "Cloudflare: signed in."
if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
  note "GitHub: signed in as $(gh api user --jq .login 2>/dev/null || echo '?')."
else
  warn "GitHub CLI is not signed in (gh auth login). Stage 2 will list GitHub steps for you to do by hand."
fi
if [[ -z "$CF_ACCOUNT_ID" ]]; then
  warn "Could not find CLOUDFLARE_ACCOUNT_ID in $CF_CONFIG."
  ask CF_ACCOUNT_ID "Paste the NAISEMA Cloudflare account ID (dashboard → account home → ⋯ → Copy account ID):"
fi
note "Account ID: $CF_ACCOUNT_ID"
if refresh_secrets; then
  note "Worker $ENV_NAME has ${SECRET_NAMES:+$(printf '%s\n' "$SECRET_NAMES" | grep -c .)} secret(s) set already."
else
  warn "Could not list the Worker's existing secrets (it may not be deployed yet). Existing secrets will not be detected, so you may be asked to set one twice."
  SECRET_NAMES=""
fi
pause "Press Enter to continue"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "GitHub: deploy settings"
say "Deploys stay skipped until the repository variable CLOUDFLARE_ACCOUNT_ID exists, and"
say "each environment holds its own Cloudflare API token (runbook, Connect GitHub)."
if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
  set_var CLOUDFLARE_ACCOUNT_ID "$CF_ACCOUNT_ID"
  gh api -X PUT "repos/${REPO}/environments/${ENV_NAME}" >/dev/null 2>&1 \
    && note "GitHub environment '${ENV_NAME}' exists." \
    || warn "could not create the '${ENV_NAME}' environment; create it at https://github.com/${REPO}/settings/environments"
else
  SKIPPED+=("GitHub variable CLOUDFLARE_ACCOUNT_ID=$CF_ACCOUNT_ID and the '$ENV_NAME' environment (https://github.com/$REPO/settings/environments)")
fi
if [[ "$ENV_NAME" == "production" ]]; then
  open_url "https://github.com/${REPO}/settings/environments"
  step "Open the 'production' environment and tick Required reviewers. Add yourself (and the backup technical owner once named). Save."
  pause "Done? Press Enter"
fi
say ""
say "Now the deploy token. Cloudflare tokens can't be limited to one environment, so this one is"
say "stored only in the ${ENV_NAME} GitHub environment."
open_url "https://dash.cloudflare.com/profile/api-tokens"
step "Create Token → Create Custom Token. Name it 'naisema-${ENV_NAME}-deploy'."
step "Account permissions: Workers Scripts: Edit; D1: Edit; Workers R2 Storage: Edit; Queues: Edit; Containers: Edit; Cloudflare Images: Edit; Account Settings: Read."
step "Zone permissions (zone naisema.com): Workers Routes: Edit; DNS: Edit."
step "Account Resources: only the NAISEMA account. Create, then copy the token (shown once)."
ask_secret CF_DEPLOY_TOKEN "Paste the deploy token:"
if [[ -n "${CF_DEPLOY_TOKEN:-}" ]]; then
  set_env_secret CLOUDFLARE_API_TOKEN "$CF_DEPLOY_TOKEN"
else
  SKIPPED+=("CLOUDFLARE_API_TOKEN for the $ENV_NAME GitHub environment (nothing pasted)")
fi
unset CF_DEPLOY_TOKEN

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Sign-in secret (BETTER_AUTH_SECRET)"
say "A long random value that signs staff and learner sessions. Generated here; you never see it."
warn "Replacing it later signs everyone out and breaks enrolled authenticator apps. Only rotate it in an incident."
if want_secret BETTER_AUTH_SECRET; then
  put_secret BETTER_AUTH_SECRET "$(openssl rand -base64 32)"
fi
pause "Press Enter to continue"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Email sending from naisema.com"
say "Sign-in links, alerts and form confirmations are sent from no-reply@naisema.com."
open_url "https://dash.cloudflare.com/?to=/:account/email-service/sending"
step "Compute → Email Service → Email Sending → Onboard Domain → naisema.com."
warn "If any address at @naisema.com already receives mail, read the proposed MX records before accepting them."
step "Wait until the SPF, DKIM, DMARC and bounce records show as verified."
pause "Domain verified? Press Enter"
note "naisema.com must also be an Active zone on this Cloudflare account, with no existing DNS record for the staging/admin hostnames."
note "I can't check email delivery from here. After the first deploy, request a staff sign-in link and confirm it reaches a real inbox."

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Turnstile (the bot check on public forms)"
say "Without these two keys every public form refuses to send."
if has_secret TURNSTILE_SITE_KEY && has_secret TURNSTILE_SECRET_KEY \
   && ! confirm "Both Turnstile keys are already set. Replace them?"; then
  note "Keeping the existing Turnstile keys."
else
  open_url "https://dash.cloudflare.com/?to=/:account/turnstile"
  step "Add widget. Name: 'naisema-${ENV_NAME}'. Mode: Managed."
  if [[ "$ENV_NAME" == "production" ]]; then
    step "Hostnames: naisema.com"
  else
    step "Hostnames: staging.naisema.com"
  fi
  step "Create, then copy the Site Key and the Secret Key."
  warn "Use the real keys. The key beginning 1x0000… in wrangler.jsonc is Cloudflare's always-passes test key and protects nothing."
  ask TURNSTILE_SITE_KEY_VALUE "Paste the Site Key:"
  ask_secret TURNSTILE_SECRET_KEY_VALUE "Paste the Secret Key:"
  if [[ "${TURNSTILE_SITE_KEY_VALUE:-}" == 1x0000* || "${TURNSTILE_SECRET_KEY_VALUE:-}" == 1x0000* ]]; then
    warn "That looks like a Cloudflare TEST key; not saving it. Re-run this stage with the real keys."
    SKIPPED+=("Turnstile keys: a test key was pasted")
  elif [[ -n "${TURNSTILE_SITE_KEY_VALUE:-}" && -n "${TURNSTILE_SECRET_KEY_VALUE:-}" ]]; then
    put_secret TURNSTILE_SITE_KEY "$TURNSTILE_SITE_KEY_VALUE"
    put_secret TURNSTILE_SECRET_KEY "$TURNSTILE_SECRET_KEY_VALUE"
  else
    SKIPPED+=("Turnstile keys (a field was left empty)")
  fi
  unset TURNSTILE_SITE_KEY_VALUE TURNSTILE_SECRET_KEY_VALUE
fi

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Backups: buckets, deletion-ledger lock and encryption key"
say "Deploys fail until the backups and ledger buckets exist (runbook, Backups and restoring)."
for bucket in "naisema-${ENV_NAME}-backups" "naisema-${ENV_NAME}-ledger"; do
  out=$(wr r2 bucket create "$bucket" --location oc 2>&1) && note "created $bucket" \
    || { if grep -qi "already exists" <<<"$out"; then note "$bucket already exists"; else warn "$bucket: $(tail -n1 <<<"$out")"; SKIPPED+=("R2 bucket $bucket: create it with pnpm wrangler r2 bucket create $bucket --location oc"); fi; }
done
say ""
warn "Locking the ledger is permanent: its entries can then never be deleted, by anyone. That is the point (ADR-0009)."
if confirm "Lock naisema-${ENV_NAME}-ledger now?"; then
  for prefix in learner/ object/; do
    if out=$(wr r2 bucket lock add "naisema-${ENV_NAME}-ledger" --name keep-entries --prefix "$prefix" --retention-indefinite 2>&1); then
      note "locked prefix $prefix"
    else
      warn "lock $prefix: $(tail -n1 <<<"$out")"
      SKIPPED+=("Ledger lock for prefix $prefix (run: pnpm wrangler r2 bucket lock add --help, options may have moved)")
    fi
  done
else
  SKIPPED+=("Lock the ledger: pnpm wrangler r2 bucket lock add naisema-${ENV_NAME}-ledger --name keep-entries --prefix learner/ --retention-indefinite (and object/)")
fi
pause "Press Enter to set the backup encryption key"
_clear
printf '\n%s%s▸ Stage 6/%s · Backup encryption key%s\n' "$BOLD" "$BLUE" "$TOTAL_STAGES" "$RESET"
if want_secret BACKUP_ENCRYPTION_KEY; then
  BACKUP_KEY=$(openssl rand -base64 32)
  put_secret BACKUP_ENCRYPTION_KEY "$BACKUP_KEY"
  if has_secret BACKUP_ENCRYPTION_KEY; then
    warn "Cloudflare can never show this key again. Without it every backup is unreadable."
    step "Save it in the NAISEMA password manager NOW, apart from Cloudflare, labelled 'naisema-${ENV_NAME} backup key'."
    printf '\n      %s%s%s\n\n' "$BOLD" "$BACKUP_KEY" "$RESET"
    until confirm "Saved in the password manager?"; do say "Please save it before continuing; the screen clears next."; done
  fi
  unset BACKUP_KEY
fi

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Newsletter (Buttondown)"
if [[ "$ENV_NAME" != "production" ]]; then
  say "Staging never sends sign-ups to Buttondown (it writes them to a table), so there is nothing to do here."
  pause "Press Enter to continue"
else
  say "Production only. Sign-ups need double opt-in switched on."
  open_url "https://buttondown.com/requests"
  step "Create the NAISEMA newsletter if it doesn't exist. Record who holds the account in docs/handover/vendors-and-accounts.md."
  open_url "https://buttondown.com/settings/subscribing"
  step "Turn on 'Require confirmation' (double opt-in)."
  open_url "https://buttondown.com/settings/programming"
  step "Create an API key and copy it."
  if want_secret BUTTONDOWN_API_KEY; then
    ask_secret BUTTONDOWN_KEY_VALUE "Paste the Buttondown API key:"
    if [[ -n "${BUTTONDOWN_KEY_VALUE:-}" ]]; then put_secret BUTTONDOWN_API_KEY "$BUTTONDOWN_KEY_VALUE"; else SKIPPED+=("BUTTONDOWN_API_KEY (nothing pasted)"); fi
    unset BUTTONDOWN_KEY_VALUE
  fi
fi

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Monitoring token and who gets alerted"
say "The hourly monitor and the cost report read figures from Cloudflare, and email ALERT_EMAILS."
if want_secret MONITORING_API_TOKEN; then
  open_url "https://dash.cloudflare.com/profile/api-tokens"
  step "Create Token → Create Custom Token. Name: 'naisema-${ENV_NAME}-monitoring'."
  step "Permissions: Account → Account Analytics → Read; Account → Stream → Read. Limit it to the NAISEMA account. Read-only."
  ask_secret MONITORING_TOKEN_VALUE "Paste the monitoring token:"
  if [[ -n "${MONITORING_TOKEN_VALUE:-}" ]]; then put_secret MONITORING_API_TOKEN "$MONITORING_TOKEN_VALUE"; else SKIPPED+=("MONITORING_API_TOKEN (nothing pasted)"); fi
  unset MONITORING_TOKEN_VALUE
fi
say ""
if want_secret ALERT_EMAILS; then
  say "Alert addresses: the technical owner, plus the backup once named (launch blocker #6)."
  ask ALERT_EMAILS_VALUE "Comma-separated email addresses:"
  if [[ "${ALERT_EMAILS_VALUE:-}" == *@* ]]; then
    put_secret ALERT_EMAILS "${ALERT_EMAILS_VALUE// /}"
    [[ "$ALERT_EMAILS_VALUE" != *,* ]] && SKIPPED+=("Add the backup technical owner to ALERT_EMAILS once #6 names one (re-run this stage)")
  else
    SKIPPED+=("ALERT_EMAILS: no address entered; alerts only reach the logs until it is set")
  fi
  unset ALERT_EMAILS_VALUE
fi

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Stream: read-only access to the video masters"
say "Stream copies each video from a pre-signed address. This key can read masters and nothing else."
say "Skip this stage and the next if there is no Stream account yet; videos then say they aren't set up."
if ! confirm "Is there a Cloudflare Stream subscription on the account, and do you want to set up video now?"; then
  SKIPPED+=("Stream setup (stages 9 and 10): subscribe to Stream, then re-run this wizard")
  STREAM_SKIP=1
else
  STREAM_SKIP=0
  if want_secret R2_MASTERS_ACCESS_KEY_ID || want_secret R2_MASTERS_SECRET_ACCESS_KEY; then
    open_url "https://dash.cloudflare.com/?to=/:account/r2/api-tokens"
    step "Manage API tokens → Create API token. Permission: Object Read only."
    step "Specify bucket: naisema-${ENV_NAME}-video-masters (only this one). Create."
    step "Copy the Access Key ID and the Secret Access Key (shown once). Ignore the other values on the page."
    ask_secret R2_KEY_ID_VALUE "Paste the Access Key ID:"
    ask_secret R2_KEY_SECRET_VALUE "Paste the Secret Access Key:"
    if [[ -n "${R2_KEY_ID_VALUE:-}" && -n "${R2_KEY_SECRET_VALUE:-}" ]]; then
      put_secret R2_MASTERS_ACCESS_KEY_ID "$R2_KEY_ID_VALUE"
      put_secret R2_MASTERS_SECRET_ACCESS_KEY "$R2_KEY_SECRET_VALUE"
    else
      SKIPPED+=("R2_MASTERS_ACCESS_KEY_ID / R2_MASTERS_SECRET_ACCESS_KEY (a field was left empty)")
    fi
    unset R2_KEY_ID_VALUE R2_KEY_SECRET_VALUE
  fi
fi

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Stream: API token, signing key, customer code and webhook"
if [[ "${STREAM_SKIP:-1}" == "1" ]]; then
  say "Skipped: Stream was not set up in the last stage."
  pause "Press Enter to continue"
else
  open_url "https://dash.cloudflare.com/profile/api-tokens"
  step "Create Token → Create Custom Token. Name: 'naisema-${ENV_NAME}-stream'. Permission: Account → Stream → Edit, and nothing else."
  ask_secret STREAM_TOKEN_VALUE "Paste the Stream token:"
  if [[ -z "${STREAM_TOKEN_VALUE:-}" ]]; then
    SKIPPED+=("Stream token, signing key, customer code and webhook (no token pasted)")
  else
    want_secret STREAM_API_TOKEN && put_secret STREAM_API_TOKEN "$STREAM_TOKEN_VALUE"

    if ! has_secret STREAM_SIGNING_KEY_ID || ! has_secret STREAM_SIGNING_KEY_JWK; then
      say "Creating a signing key for playback tokens (it is not shown or saved anywhere else)..."
      resp=$(cf_api POST "/accounts/${CF_ACCOUNT_ID}/stream/keys" "$STREAM_TOKEN_VALUE" || true)
      key_id=$(printf '%s' "$resp" | json_field 'x.success === true ? x.result.id : undefined' || true)
      key_jwk=$(printf '%s' "$resp" | json_field 'x.success === true ? x.result.jwk : undefined' || true)
      if [[ -n "$key_id" && -n "$key_jwk" ]]; then
        put_secret STREAM_SIGNING_KEY_ID "$key_id"
        put_secret STREAM_SIGNING_KEY_JWK "$key_jwk"
      else
        warn "Cloudflare refused: $(printf '%s' "$resp" | json_field 'x.errors.map(e => e.message).join("; ")' || echo 'no readable answer')"
        SKIPPED+=("Stream signing key (check the token has Stream: Edit and the account has Stream)")
      fi
      unset resp key_id key_jwk
    else
      note "Signing key already set; not creating another."
    fi

    if want_secret STREAM_CUSTOMER_CODE; then
      open_url "https://dash.cloudflare.com/?to=/:account/stream"
      step "Open any video in Stream (upload a short test clip if there are none; it can be deleted afterwards)."
      step "Copy its playback or embed address. It contains customer-xxxxxxxx.cloudflarestream.com."
      ask CUSTOMER_INPUT "Paste the address (or just the code):"
      code=$(printf '%s' "${CUSTOMER_INPUT:-}" | sed -nE 's#.*customer-([A-Za-z0-9]+).*#\1#p' | head -n1)
      [[ -z "$code" ]] && code=$(printf '%s' "${CUSTOMER_INPUT:-}" | tr -cd 'A-Za-z0-9')
      if [[ -n "$code" ]]; then put_secret STREAM_CUSTOMER_CODE "$code"; else SKIPPED+=("STREAM_CUSTOMER_CODE (nothing usable pasted)"); fi
      unset CUSTOMER_INPUT code
    fi

    if [[ "$ENV_NAME" == "production" ]]; then
      say ""
      say "Stream sends every account's reports to ONE webhook address; it must point at production."
      if want_secret STREAM_WEBHOOK_SECRET && confirm "Point the account's Stream webhook at https://naisema.com/webhooks/stream?"; then
        resp=$(cf_api PUT "/accounts/${CF_ACCOUNT_ID}/stream/webhook" "$STREAM_TOKEN_VALUE" '{"notificationUrl":"https://naisema.com/webhooks/stream"}' || true)
        hook_secret=$(printf '%s' "$resp" | json_field 'x.success === true ? x.result.secret : undefined' || true)
        if [[ -n "$hook_secret" ]]; then
          put_secret STREAM_WEBHOOK_SECRET "$hook_secret"
        else
          warn "Cloudflare refused: $(printf '%s' "$resp" | json_field 'x.errors.map(e => e.message).join("; ")' || echo 'no readable answer')"
          SKIPPED+=("Stream webhook and STREAM_WEBHOOK_SECRET (see runbook, Setting up Stream, step 6)")
        fi
        unset resp hook_secret
      fi
    else
      note "Staging shares the account but never hears the webhook (it's pointed at production); its videos become ready through the daily job or 'Check with Stream now'."
    fi
    unset STREAM_TOKEN_VALUE
    note "Once Stream is in use, add its secrets to production's secrets.required in wrangler.jsonc (runbook)."
  fi
  pause "Press Enter to continue"
fi

# ── 11 ────────────────────────────────────────────────────────────────────
stage "Cloudflare billing alerts"
say "These back up the app's own cost emails, which stop if the Worker stops. Ceiling: AUD 100 a month."
open_url "https://dash.cloudflare.com/?to=/:account/notifications"
step "Notifications → Add. Choose the usage-based billing alerts offered for Stream and for R2."
step "Suggested levels (adjust once real usage is known):"
say "      Stream minutes stored:     5,400 (50%) and 9,300 (80%)"
say "      Stream minutes delivered:  25,000 in the month"
say "      R2 storage:                500 GB"
step "Send them to the technical owner (and the backup)."
note "If Stream or R2 usage alerts aren't offered for the account yet, note that and revisit once they appear."
pause "Alerts created? Press Enter"

# ── 12 ────────────────────────────────────────────────────────────────────
stage "Check the secrets the deploy requires"
if [[ "$ENV_NAME" == "production" ]]; then
  required=(BETTER_AUTH_SECRET TURNSTILE_SITE_KEY TURNSTILE_SECRET_KEY BUTTONDOWN_API_KEY BACKUP_ENCRYPTION_KEY)
else
  required=(BETTER_AUTH_SECRET TURNSTILE_SITE_KEY TURNSTILE_SECRET_KEY BACKUP_ENCRYPTION_KEY)
fi
optional=(MONITORING_API_TOKEN ALERT_EMAILS STREAM_API_TOKEN STREAM_SIGNING_KEY_ID STREAM_SIGNING_KEY_JWK STREAM_CUSTOMER_CODE R2_MASTERS_ACCESS_KEY_ID R2_MASTERS_SECRET_ACCESS_KEY)
[[ "$ENV_NAME" == "production" ]] && optional+=(STREAM_WEBHOOK_SECRET)
if refresh_secrets; then
  say "Required by wrangler.jsonc for ${ENV_NAME} (a deploy fails without these):"
  for n in "${required[@]}"; do
    if has_secret "$n"; then printf '    %s✓%s %s\n' "$GREEN" "$RESET" "$n"; else printf '    %s✗%s %s\n' "$RED" "$RESET" "$n"; SKIPPED+=("Required secret $n is not set on $ENV_NAME"); fi
  done
  say ""
  say "Needed for monitoring, alerts and video:"
  for n in "${optional[@]}"; do
    if has_secret "$n"; then printf '    %s✓%s %s\n' "$GREEN" "$RESET" "$n"; else printf '    %s·%s %s (not set)\n' "$YELLOW" "$RESET" "$n"; fi
  done
else
  warn "Could not list the Worker's secrets. The Worker may not exist until its first deploy; the list is checked again by the deploy itself."
  SKIPPED+=("Re-check secrets after the first deploy: pnpm wrangler secret list --env $ENV_NAME")
fi
pause "Press Enter to continue"

# ── 13 ────────────────────────────────────────────────────────────────────
stage "First administrator"
say "Needs the database migrated, which the first deploy does. If ${ENV_NAME} hasn't deployed yet,"
say "say no here and run the command at the end afterwards."
if confirm "Has ${ENV_NAME} been deployed (migrations applied)?"; then
  ask ADMIN_EMAIL "Email address of the first administrator:"
  if [[ "${ADMIN_EMAIL:-}" == *@* ]]; then
    pnpm staff:grant --env "$ENV_NAME" --email "$ADMIN_EMAIL" --role administrator \
      || SKIPPED+=("First administrator: pnpm staff:grant --env $ENV_NAME --email $ADMIN_EMAIL --role administrator")
  else
    SKIPPED+=("First administrator: pnpm staff:grant --env $ENV_NAME --email <address> --role administrator")
  fi
else
  SKIPPED+=("After the first deploy: pnpm staff:grant --env $ENV_NAME --email <address> --role administrator")
fi

# ──────────────────────────────────────────────────────────────────────────

finish
if (( ${#WORKER_SET[@]} )); then note "set ${#WORKER_SET[@]} Worker secret(s) on $ENV_NAME: ${WORKER_SET[*]}"; fi
if (( ${#GH_ENV_SET[@]} )); then note "set ${#GH_ENV_SET[@]} GitHub $ENV_NAME environment secret(s): ${GH_ENV_SET[*]}"; fi
printf '\n'
note "Not done by this wizard (see docs/launch-checklist.md):"
note "  - record who holds each account in docs/handover/vendors-and-accounts.md"
note "  - choose and configure the external uptime monitor (#20), then record it in docs/decision-log.md"
note "  - run the restore drill (#34) and the AC-08 rehearsal (#62)"
printf '\n'
